def get_prime_factors(N):
    factors = {}
    d = 2
    temp = N
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_power_of_prime(N, p):
    if N <= 0 or p <= 1:
        return None
    if N == 1:
        return 0 # Special case, but we require exponent >= 2

    if N % p != 0:
        return None

    exponent = 0
    temp = N
    while temp > 1:
        if temp % p != 0:
            return None # Not a power of p
        temp //= p
        exponent += 1
    return exponent

