def get_prime_power(N):
    """
    Checks if N is a perfect prime power p^a (a >= 2).
    Returns (p, a) if it is, otherwise returns (None, None).
    """
    if N <= 1:
        return (None, None)

    # Check for prime factors
    factors = {}
    d = 2
    temp = N
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    if len(factors) == 1:
        p = list(factors.keys())[0]
        a = list(factors.values())[0]
        if a >= 2:
            return (p, a)
    return (None, None)

